beforeHooks.code:
const isFlipkartSelfEmp = constants.PARTNER === 'Flipkart' && constants.EMP_TYPE === 'SELFEMP';
// GSTIN_SCENARIO env override — lets the same suite exercise OS-2254 Rule 0
// (GST Match) without code changes:
//   MATCH (default) — known-good GSTIN that IS in the Karza soft-pull results
//   NONE            — gstin omitted entirely (Rule 0 must be skipped, not fired)
//   INVALID         — syntactically malformed GSTIN
//   MISMATCH        — well-formed GSTIN that is NOT in the Karza soft-pull results
const GSTIN_SCENARIOS = {
    MATCH:    '11AAACR5055K1ZK',
    NONE:     null,
    INVALID:  'GARBAGE12345',
    MISMATCH: '27ABCDE1234F1Z5',
};
const gstinScenario = (process.env.GSTIN_SCENARIO || 'MATCH').toUpperCase();
const scenarioGstin = Object.prototype.hasOwnProperty.call(GSTIN_SCENARIOS, gstinScenario)
    ? GSTIN_SCENARIOS[gstinScenario] : GSTIN_SCENARIOS.MATCH;
console.log(`  GSTIN_SCENARIO=${gstinScenario} → gstin sent: ${scenarioGstin ?? '(none)'}`);
// Single source of truth — `extra` (dot-path keys for the applicationCreate
// payload) is derived from sentEmployment instead of being hand-duplicated,
// so the two can never drift out of sync.
sentEmployment = isFlipkartSelfEmp ? {
    emp_type:           'SELFEMP',
    annual_turnover:    'Rs.0 to 40 lakhs',
    nature_of_business: 'MANUFACTURER',
    business_type:      'PROPRIETORSHIP',
    ...(scenarioGstin ? { gstin: scenarioGstin } : {}),
    business_name:      'Sharma Traders Pvt Ltd',
} : {};
const extra = Object.fromEntries(
    Object.entries(sentEmployment).map(([key, value]) => [`employment.${key}`, value])
);
Appresponse = await CommonAPI.applicationCreate(panNumber, mobileNumber, extra);
const { applicationCreateres } = Appresponse;
app_id = applicationCreateres.body.response.application_id;
await saveAppData(app_id);
CommonAPI.writeTestContext({ appId: app_id });

