// NOTE: only gated on partner/emp_type, NOT on gstin being sent. Per OS-2254,
// Rule 0 (GST match) and the soft-pull side of Rule A/B are the only things that
// skip when no GSTIN is sent — Rule A's create-side check and Rule C (income/
// turnover) are independent of GST and must still be evaluated. Karza's soft-pull
// is keyed by PAN, not GSTIN, so it still returns real data even with no GSTIN sent.
if (!(constants.PARTNER === 'Flipkart' && constants.EMP_TYPE === 'SELFEMP')) {
    console.log('  Skipping SENP rule evaluation — only runs for Flipkart SELFEMP');
    this.skip();
}
