karzaForReport = karza;
senpDecision = CommonAPI.deriveSenpExpectedDecision(sentEmployment, karza.gst, karza.karzaGstins);
console.log(`\n  SENP Rule Evaluation — derive expected decision (Flipkart SELFEMP)`);
CommonAPI.printKarzaGstPanels(karza);
CommonAPI.printSenpRulePanel(senpDecision);
console.log(`\n  → Derived expected decision: ${senpDecision.expectedDecision}`);

