// Vendor-log rows carry their OMNI type at DV-Application.Spare.String01 — NOT
// policySegmentId (that key only exists on underwriting_transaction_log/OMNI_1 rows).
const types = omniRows.map(r => {
    const input = typeof r.input === 'string' ? JSON.parse(r.input) : r.input;
    return input?.['DV-Application']?.['Spare']?.['String01'] ?? 'UNKNOWN';
});
console.log(`  Found OMNI rows: ${types.join(', ')}`);
addContext(this, { title: 'OMNI vendor log — rows found', value: { types, count: omniRows.length } });
expect(omniRows.length, 'expected at least one OMNI row in underwriting_vendor_transaction_log').to.be.greaterThan(0);

// Reuses CommonAPI.extractGstFromOmniInput (built for underwriting_transaction_log
// OMNI_1/PRE/POST rows) where the shape matches; vendor-log rows don't carry the
// CUSTOMER.EMPLOYMENT[0].GST path that helper looks for, so we also attach the full
// raw input so GST-related fields can be inspected wherever they actually live.
for (const row of omniRows) {
    const input = typeof row.input === 'string' ? JSON.parse(row.input) : row.input;
    const omniType = input?.['DV-Application']?.['Spare']?.['String01'] ?? 'UNKNOWN';
    const gst = CommonAPI.extractGstFromOmniInput(input);
    console.log(`\n  vendor — underwriting_vendor_transaction_log — ${omniType} — GST (input): ${JSON.stringify(gst)}`);
    addContext(this, { title: `${omniType} vendor log — full INPUT (raw)`, value: input });
    addContext(this, { title: `${omniType} vendor log — GST sub-block (if present)`, value: gst });
}

