    expect(datasutramInput.appId).to.equal(app_id, `Application ID mismatch. Expected: ${app_id}, Got: ${datasutramInput.appId}`);

    // Verify phone number matches mobile from Appcreation.json
    expect(datasutramInput.phone).to.equal(expectedMobile, `Phone number mismatch. Expected: ${expectedMobile}, Got: ${datasutramInput.phone}`);

    // Verify output exists
    datasutramOutput = datasutramRow.output;

    // Parse output if it's a string (JSON)
    if (datasutramOutput && typeof datasutramOutput === 'string') {
        try {
            datasutramOutput = JSON.parse(datasutramOutput);
        } catch (e) {
            console.warn('Failed to parse Datasutram output as JSON: ' + e.message);
            // If parsing fails, treat as empty output
            datasutramOutput = null;
        }
    }

    // Extract dsTrustScore and tagIds from output
    // If output is empty or missing data, set default values
    if (!datasutramOutput || !datasutramOutput.data) {
        // Empty output case: set TAG_IDS to [] and TRUST_SCORE to "NA"
        dsTrustScore = "NA";
        tagIds = [];
        console.log('⚠️ Datasutram output is empty. Setting TAG_IDS: [] and TRUST_SCORE: "NA"');
    } else {
        // Extract from output data
        dsTrustScore = datasutramOutput.data.dsTrustScore;
        tagIds = datasutramOutput.data.tagIds;

        // If dsTrustScore is undefined or null, set to "NA"
        if (dsTrustScore === undefined || dsTrustScore === null) {
            dsTrustScore = "NA";
        }

        // If tagIds is missing or not an array, set to empty array
        if (!tagIds || !Array.isArray(tagIds)) {
            tagIds = [];
        }
    }

