    // Query underwriting_transaction_log for OMNI_HC, OMNI_PRE and OMNI_POST
    const query = 'SELECT * FROM services.underwriting_transaction_log WHERE applicationid = ? ORDER BY createdAt DESC;';
    const params = [app_id];
    const rows = await CommonAPI.runQuery(query, params);
    if (!rows || rows.length === 0) {
        throw new Error('No rows returned from underwriting_transaction_log query');
    }
    let omniHcRow = null;
    let omniPreRow = null;
    let omniPostRow = null;
    // Find OMNI_HC, OMNI_PRE and OMNI_POST rows
    for (const row of rows) {
        const omnitype = row.input?.policySegmentId;
        if (omnitype === "OMNI_HC" && !omniHcRow) { omniHcRow = row; }
        if (omnitype === "OMNI_PRE" && !omniPreRow) { omniPreRow = row; }
        if (omnitype === "OMNI_POST" && !omniPostRow) { omniPostRow = row; }
        if (omniHcRow && omniPreRow && omniPostRow) { break; }
    }

    if (!omniPreRow) {
        throw new Error('OMNI_PRE transaction not found in underwriting_transaction_log');
    }

    if (!omniPostRow) {
        throw new Error('OMNI_POST transaction not found in underwriting_transaction_log');
    }

    // Extract TRUST_SCORE and TAG_IDS from OMNI_PRE
    const omniPreDatasutram = omniPreRow.input?.MODEL?.DATASUTRAM;
    const omniPreTrustScore = omniPreDatasutram?.TRUST_SCORE;
    const omniPreTagIds = omniPreDatasutram?.TAG_IDS;

    // Extract TRUST_SCORE and TAG_IDS from OMNI_POST
    const omniPostDatasutram = omniPostRow.input?.MODEL?.DATASUTRAM;
    const omniPostTrustScore = omniPostDatasutram?.TRUST_SCORE;
    const omniPostTagIds = omniPostDatasutram?.TAG_IDS;

    // Verify TRUST_SCORE and TAG_IDS exist in OMNI_PRE
    if (omniPreTrustScore === undefined || omniPreTrustScore === null) {
        throw new Error('TRUST_SCORE is missing in OMNI_PRE input');
    }

    if (omniPreTagIds === undefined || omniPreTagIds === null || !Array.isArray(omniPreTagIds)) {
        throw new Error('TAG_IDS is missing or not an array in OMNI_PRE input');
    }

    // Verify TRUST_SCORE and TAG_IDS exist in OMNI_POST
    if (omniPostTrustScore === undefined || omniPostTrustScore === null) {
        throw new Error('TRUST_SCORE is missing in OMNI_POST input');
    }

    if (omniPostTagIds === undefined || omniPostTagIds === null || !Array.isArray(omniPostTagIds)) {
        throw new Error('TAG_IDS is missing or not an array in OMNI_POST input');
    }

    // Convert dsTrustScore to string for comparison (since TRUST_SCORE is a string in OMNI)
    // If dsTrustScore is "NA" (from empty output), use it directly; otherwise convert to string
    const dsTrustScoreStr = (dsTrustScore === "NA") ? "NA" : String(dsTrustScore);

